O que aparece na tela com `<Avatar nome="Ana Clara Souza" tamanho="lg" />`?

```jsx
const medidas = { sm: 32, md: 48, lg: 72 };

function iniciais(nome) {
  return nome.split(' ').filter(Boolean).slice(0, 2)
    .map((parte) => parte[0].toUpperCase()).join('');
}

export default function Avatar({ uri, nome = '', tamanho = 'md' }) {
  const lado = medidas[tamanho];
  const forma = { width: lado, height: lado, borderRadius: lado / 2 };
  if (uri) return <Image source={{ uri }} style={forma} />;
  return <View style={forma}><Text>{iniciais(nome)}</Text></View>;
}
```
